<?php
namespace App\Providers;
use App\Contracts\FaceProvider;use App\Services\Face\{FakeFaceProvider,PythonFaceProvider,RekognitionFaceProvider};use Aws\Rekognition\RekognitionClient;use Illuminate\Support\ServiceProvider;use InvalidArgumentException;
class FaceServiceProvider extends ServiceProvider{private function deletion(string$operation,array$references):void{$row=\App\Models\ProviderDeletionOperation::create(['uuid'=>(string)\Illuminate\Support\Str::uuid(),'provider'=>config('face.provider'),'operation'=>$operation,'provider_references'=>$references,'state'=>'queued']);\App\Jobs\ExecuteProviderDeletion::dispatch($row->id);}public function boot():void{\App\Models\MediaAsset::deleting(function($asset){$rows=\App\Models\IndexedFace::with('faceCollection')->where('media_asset_id',$asset->id)->get()->groupBy('face_collection_id');foreach($rows as$faces)$this->deletion('faces',['collection'=>$faces->first()->faceCollection->provider_collection_ref,'face_ids'=>$faces->pluck('provider_face_ref')->all()]);});\App\Models\Group::deleting(function($group){if($c=\App\Models\FaceCollection::where('group_id',$group->id)->first())$this->deletion('collection',['collection'=>$c->provider_collection_ref]);});}public function register():void{$this->app->singleton(FaceProvider::class,function(){return match(config('face.provider')){'fake'=>new FakeFaceProvider(),'python'=>new PythonFaceProvider(),'rekognition'=>new RekognitionFaceProvider(new RekognitionClient(['version'=>'latest','region'=>config('face.rekognition_region'),'credentials'=>config('filesystems.disks.s3.key')?['key'=>config('filesystems.disks.s3.key'),'secret'=>config('filesystems.disks.s3.secret'),'token'=>config('filesystems.disks.s3.token')]:null])),default=>throw new InvalidArgumentException('Unsupported FACE_PROVIDER.')};});}}
